<script setup lang="ts">
import {computed,reactive,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowRight,Copy,Plus,RotateCcw} from 'lucide-vue-next'
import Panel from '../components/Panel.vue'
import Modal from '../components/Modal.vue'
import TelemetryChart from '../components/TelemetryChart.vue'
import {useWorkspace} from '../stores/workspace'
import {metricInfo,statusText} from '../domain'
import type {Detection,Metric} from '../domain'
import {samplesFor} from '../services/demo'
import {csv,time} from '../utils'
const listPage=ref(1)
const store=useWorkspace(),route=useRoute(),router=useRouter(),showList=ref(false),showForm=ref(false),error=ref(''),selected=ref<string[]>([]),focus=ref(''),query=ref(''),status=ref(''),all=ref(false),chart=ref<InstanceType<typeof TelemetryChart>>(),analysisFailure=ref(false),replay=ref(false)
const tasks=computed(()=>store.state.detections.filter(d=>(all.value||d.context.segment.id===store.context?.segment.id)&&(!query.value||(d.id+d.name).includes(query.value))&&(!status.value||d.status===status.value))),task=computed(()=>route.params.id?store.state.detections.find(d=>d.id===route.params.id):tasks.value[0])
const listRows=computed(()=>tasks.value.slice((listPage.value-1)*20,listPage.value*20)),listPages=computed(()=>Math.max(1,Math.ceil(tasks.value.length/20)))
watch([query,status,all],()=>listPage.value=1)
const form=reactive({name:'管段时序异常检测',start:'2026-11-03T00:00',end:'2026-11-03T08:00',metrics:['supply','return','pressure','flow'] as Metric[],threshold:3.4,scenario:'anomaly' as Detection['scenario'],parentId:''})
watch(()=>route.query.create,v=>{if(v){open();if(typeof route.query.start==='string')form.start=route.query.start;if(typeof route.query.end==='string')form.end=route.query.end;if(typeof route.query.metric==='string'&&route.query.metric!=='all')form.metrics=[route.query.metric as Metric]}},{immediate:true})
watch(()=>task.value?.id,()=>{selected.value=typeof route.query.selected==='string'?(task.value?.anomalies.filter(a=>String(route.query.selected).split(',').includes(a.id)).map(a=>a.id)??[]):(task.value?.anomalies.map(a=>a.id)??[]);focus.value='';showList.value=false},{immediate:true});watch(()=>task.value?.status,s=>{if(s==='success')selected.value=task.value?.anomalies.map(a=>a.id)??[]})
function open(copy?:Detection){error.value='';if(copy){store.select(copy.context.segment.id);Object.assign(form,{name:copy.name+'（副本）',start:copy.start,end:copy.end,metrics:[...copy.metrics],threshold:copy.threshold,scenario:copy.scenario,parentId:copy.id})}else{form.metrics=[...(store.context?.segment.metrics??[])];form.parentId=''}showForm.value=true}
function submit(){try{const id=store.createDetection({...form,metrics:[...form.metrics]});showForm.value=false;router.push('/detections/'+id)}catch(e){error.value=(e as Error).message}}
function retry(){if(!task.value)return;try{const id=store.createDetection({...task.value,name:task.value.name+'（重试）',scenario:'anomaly',parentId:task.value.id});router.push('/detections/'+id)}catch(e){store.notify((e as Error).message)}}
function analyze(){if(!task.value)return;try{router.push('/diagnosis/'+store.createAnalysis(task.value.id,selected.value,analysisFailure.value?'failure':'success'))}catch(e){store.notify((e as Error).message)}}
function report(){if(task.value)router.push('/diagnosis/'+store.createReport(task.value.id))}
function exportCsv(){if(!task.value)return;csv([['异常编号','参数','开始','结束','观测','基准','单位','程度'],...task.value.anomalies.map(a=>[a.id,metricInfo[a.metric].label,time(a.start),a.end?time(a.end):'持续中',a.value,a.baseline,metricInfo[a.metric].unit,a.level])],task.value.id+'-异常.csv')}
function replayAnomaly(id:string){focus.value=id;replay.value=true;store.notify('已将图表定位到异常前后区间，可拖动缩放条回看。')}
</script>
<template><div class="page-stack"><div class="page-actions"><div class="flex wrap"><h2>异常检测</h2><span class="badge orange">时序残差 · 演示算法</span></div><div class="flex"><button class="secondary" @click="showList=!showList">{{showList?'收起任务记录':'任务记录'}}</button><button class="primary" @click="open()"><Plus :size="16"/>新建检测</button></div></div>
<Panel v-if="showList||!task" title="历史检测任务"><div class="filter-bar"><input v-model="query" aria-label="搜索检测任务" placeholder="搜索任务编号或名称"/><select v-model="status" aria-label="检测任务状态"><option value="">全部状态</option><option v-for="(text,s) in statusText" :key="s" :value="s">{{text}}</option></select><label class="check-label"><input v-model="all" type="checkbox"/>全部管段</label><button class="secondary" @click="query='';status='';all=false">重置</button></div><div class="table-wrap"><table><thead><tr><th>任务</th><th>所属管段</th><th>创建时间</th><th>状态</th><th>异常数</th><th>操作</th></tr></thead><tbody><tr v-for="d in listRows" :key="d.id"><td>{{d.name}}<small>{{d.id}}</small></td><td>{{d.context.segment.name}}</td><td>{{time(d.createdAt)}}</td><td><span :class="['badge',d.status==='failed'?'red':'green']">{{statusText[d.status]}}</span></td><td>{{d.status==='success'?d.anomalies.length:'—'}}</td><td><RouterLink :to="'/detections/'+d.id" class="text-button">查看</RouterLink></td></tr><tr v-if="!tasks.length"><td colspan="6" class="empty">当前范围没有匹配任务，请修改筛选或新建检测。</td></tr></tbody></table></div><div class="pagination"><span>共 {{tasks.length}} 条 · 第 {{listPage}} / {{listPages}} 页</span><button :disabled="listPage===1" @click="listPage--">上一页</button><button :disabled="listPage>=listPages" @click="listPage++">下一页</button></div></Panel>
<template v-if="task"><Panel><div class="flex wrap between"><div class="stack-small"><div class="flex wrap"><span class="badge orange">检测任务编号：{{task.id}}</span><span class="muted">{{task.context.enterprise.name}} → {{task.context.network.name}} → <b class="orange">{{task.context.segment.name}}</b></span></div><span :class="['badge',task.status==='failed'?'red':task.status==='success'?'green':'amber']">检测状态：{{statusText[task.status]}}<template v-if="task.status==='success'">（检出 {{task.anomalies.length}} 处异常）</template></span></div><div class="flex wrap"><button class="secondary" @click="open(task)"><Copy :size="16"/>复制配置</button><button class="secondary" :disabled="task.status!=='success'" @click="report">生成检测报告</button><button class="primary" :disabled="task.status!=='success'||!selected.length" @click="analyze">发起 AI诊断 <ArrowRight :size="16"/></button></div></div></Panel>
<div class="grid metrics-four"><div class="metric-card"><span class="muted">检测时序视窗</span><h3 class="mono mt">{{time(task.start)}} — {{time(task.end)}}</h3><p class="muted">参数：{{task.metrics.map(m=>metricInfo[m].label).join('、')}}</p></div><div class="metric-card"><span class="muted">核心检测算法</span><h3 class="mt">{{task.algorithm}}</h3><p class="cyan">残差系数：{{task.threshold}} σ · 演示配置</p></div><div class="metric-card"><span class="muted">数据完整率（示例）</span><div class="metric-value green">99.8<small>%</small></div><div class="bar"><span style="width:99.8%;background:#10b981"></span></div></div><div class="metric-card"><span class="muted">检出结果</span><div class="metric-value" :class="task.anomalies.length?'red':'green'">{{task.status==='success'?task.anomalies.length:'—'}}<small>项异常</small></div><p class="muted">{{task.status==='success'?(task.anomalies.length?'待人工核查':'当前范围未检出异常'):'等待执行结果'}}</p></div></div>
<Panel v-if="task.status==='queued'||task.status==='running'" title="正在执行检测"><div class="task-running"><span class="loader"></span><h3>{{statusText[task.status]}}</h3><p class="muted">演示检测正在处理所选参数，离开页面后可返回任务记录查看。</p></div></Panel><Panel v-else-if="task.status==='failed'" title="检测未完成"><p class="error">{{task.error}}</p><button class="primary mt" @click="retry">重试检测</button></Panel>
<template v-else><Panel title="供回水温差与回水压力时序诊断图谱"><template #tools><span class="muted">独立单位坐标 · {{replay?'异常区间回看':'原始数据与异常标记'}}</span><button class="icon-button" aria-label="复位视窗" @click="focus='';replay=false;chart?.reset()"><RotateCcw :size="16"/></button></template><TelemetryChart :key="task.id" ref="chart" :context="task.context" :metrics="task.metrics" :start="task.start" :end="task.end" :anomalies="task.anomalies" :focus-id="focus" @select="id=>focus=id"/><p class="chart-caption">红色虚线区域为演示异常区间，点击曲线标记或下方明细联动定位。</p></Panel>
<Panel :title="'数值异常事件清单（检出 '+task.anomalies.length+' 项）'"><template #tools><label class="check-label"><input type="checkbox" :checked="!!task.anomalies.length&&selected.length===task.anomalies.length" :disabled="!task.anomalies.length" @change="selected=selected.length===task.anomalies.length?[]:task.anomalies.map(a=>a.id)"/>全选 {{selected.length}} / {{task.anomalies.length}}</label></template><p class="muted small">异常事件仅表示观测值偏离数值规则；具体原因与解决建议请选取事件后进入 AI诊断。</p><div class="anomaly-list"><article v-for="a in task.anomalies" :key="a.id" :class="['anomaly-card',{focused:focus===a.id}]" :data-anomaly="a.id"><div class="flex wrap between"><label class="check-label"><input v-model="selected" type="checkbox" :value="a.id"/><strong>{{a.title}}</strong><span :class="['badge',a.metric==='return'?'red':'amber']">{{a.level}}</span></label><button class="secondary" @click="replayAnomaly(a.id)">区间回放</button></div><p class="orange mono">发生时段：{{time(a.start)}} — {{a.end?time(a.end):'持续中'}}</p><div class="flex wrap between"><p class="muted">检测依据：{{a.evidence}}</p><div class="comparison"><div><span>观测值</span><strong class="red">{{a.value}} {{metricInfo[a.metric].unit}}</strong></div><span>vs</span><div><span>基准值</span><strong>{{a.baseline}} {{metricInfo[a.metric].unit}}</strong></div></div></div><button class="text-button" @click="focus=a.id">在曲线中定位异常 <ArrowRight :size="14"/></button></article><div v-if="!task.anomalies.length" class="empty"><h3 class="green">检测完成，未检出异常</h3><p>此结果不代表设备已通过现场检查；可以查看曲线或生成阶段性报告。</p></div></div><div class="flex wrap between mt"><button class="secondary" :disabled="!task.anomalies.length" @click="exportCsv">导出异常时序 CSV</button><div class="flex wrap"><label class="check-label muted"><input v-model="analysisFailure" type="checkbox"/>演示分析失败场景</label><button class="primary" :disabled="!selected.length" @click="analyze">将选中异常（{{selected.length}} 项）送入 AI诊断</button></div></div></Panel></template></template>
<Modal v-if="showForm" title="新建异常检测任务" @close="showForm=false;router.replace({query:{}})"><form class="form-stack" @submit.prevent="submit"><div class="inset">当前对象：{{store.context?.enterprise.name}} / {{store.context?.network.name}} / <b class="orange">{{store.context?.segment.name??'未选择管段'}}</b><RouterLink to="/networks?pick=1" class="text-button" @click="showForm=false">切换对象</RouterLink></div><label>任务名称 *<input v-model="form.name" required maxlength="80"/></label><div class="form-grid"><label>开始时间 *<input v-model="form.start" type="datetime-local" required/></label><label>结束时间 *<input v-model="form.end" type="datetime-local" required/></label></div><p class="muted">可用演示数据：2026-11-03 00:00 至 2026-11-04 00:00</p><fieldset><legend>监测参数 *</legend><label v-for="m in store.context?.segment.metrics" :key="m" class="check-label"><input v-model="form.metrics" type="checkbox" :value="m"/>{{metricInfo[m].label}}（{{metricInfo[m].unit}}）</label><p v-if="!store.context?.segment.metrics.length" class="error">当前管段未配置监测参数，请切换对象。</p></fieldset><label>检测算法<select><option>时序残差聚类 V2.3（演示）</option></select></label><label>残差系数（σ，0–10）*<input v-model.number="form.threshold" type="number" min="0.1" max="10" step="0.1" required/></label><label>演示场景<select v-model="form.scenario"><option value="anomaly">检测到异常</option><option value="normal">未检出异常</option><option value="failure">服务失败（验证重试）</option></select></label><p class="muted">预览：{{store.context?samplesFor(store.context,form.start,form.end).filter(s=>form.metrics.includes(s.metric)).length:0}} 条演示采样 · 所选 {{form.metrics.length}} 项参数</p><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary" type="submit">创建并执行检测</button></form></Modal>
</div></template>
